write_file 0755 testing/verify-start.sh <<'ASTRONA_LAB_FILE'
#!/usr/bin/env bash
# Run by `astrona test` before the reference solution. Every outcome must fail
# on the unfinished lab, and fail with a grading result rather than a crash.
set -euo pipefail
lab_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
fail() { echo "FAIL: starting state: $*" >&2; exit 1; }
output=$(mktemp)
trap 'rm -f "$output"' EXIT
for grader in "$lab_dir"/validation/validate-*.sh; do
  outcome=$(basename "$grader" .sh)
  outcome=${outcome#validate-}
  if bash "$grader" >"$output" 2>&1; then
    cat "$output"
    fail "$outcome passed on the unfinished lab"
  fi
  if ! grep -q '^FAIL:' "$output" || grep -q '^FAIL: Unknown outcome' "$output"; then
    cat "$output"
    fail "$outcome failed without a grading result"
  fi
  echo "$outcome: $(grep -m1 '^FAIL:' "$output")"
done
echo 'PASS: every outcome fails on the unfinished lab'
ASTRONA_LAB_FILE
write_file 0755 testing/wait-solved.sh <<'ASTRONA_LAB_FILE'
#!/usr/bin/env bash
# Run by `astrona test` after the reference solution: wait, with a timeout,
# until the lab settles (restarted kubelets and API servers answer again) and
# every outcome passes, so the graders that follow see the finished state.
set -euo pipefail
lab_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
output=$(mktemp)
trap 'rm -f "$output"' EXIT
for attempt in $(seq 1 24); do
  if bash "$lab_dir/validate.sh" >"$output" 2>&1; then
    echo "PASS: the reference solution settled (attempt $attempt)"
    exit 0
  fi
  sleep 5
done
cat "$output"
echo 'FAIL: the reference solution did not pass within two minutes' >&2
exit 1
